responseFormat.typescriptTypesReference:
type Citation = {
commentId: number;
};

type Clause = {
text: string;
citations: Citation[];
};

type Sentence = {
clauses: Clause[];
};

type Paragraph = {
id: string; // e.g. "division_overview"
title: string;
sentences: Sentence[];
};

type Subtask = {
id: string;
title: string;
paragraphs: Paragraph[];
};

polisAnalysisPrompt.example:
{
"id": "group_differences",
"title": "Group Divisions",
"paragraphs": [
{
"id": "division_overview",
"title": "Overview of Group Divisions",
"sentences": [
{
"clauses": [
{
"text": "The group is most divided on how quickly the new policy should be introduced.",
"citations": [12, 15, 23]
}
]
}
]
}
]
}
]
}
